// id-migrate-send (ADR-0058). logInput/logOutput OFF: the key and the people.
export const code = async (inputs) => {
  const crypto = require('node:crypto');
  const s = (v) => (v === undefined || v === null ? '' : String(v));
  const key = inputs.migration_key, url = s(inputs.url), mode = s(inputs.mode), run = s(inputs.run);
  if (typeof key !== 'string' || key.length < 32 || key.includes('{{')) throw new Error('not_configured: migration_key');
  if (!/^https:\/\/[A-Za-z0-9.-]+\/api\/v1\/webhooks\/[A-Za-z0-9]+\/sync$/.test(url)) throw new Error('not_configured: url');
  if (mode !== 'test' && mode !== 'real') throw new Error('bad_mode');
  if (!/^[A-Za-z0-9_-]{1,40}$/.test(run)) throw new Error('bad_run');
  const people = inputs.people;
  if (!Array.isArray(people) || people.length < 1 || people.length > 10) throw new Error('bad_batch');
  const payload = JSON.stringify({ kind: 'batch', mode, run, people });
  const nowSec = () => Math.floor((Number.isFinite(inputs.now_ms) ? inputs.now_ms : Date.now()) / 1000);
  const wait = (ms) => (inputs.no_wait ? Promise.resolve() : new Promise((r) => setTimeout(r, ms)));
  let last = 'no_attempt';
  for (let attempt = 1; attempt <= 3; attempt++) {
    const ts = String(nowSec()), rid = 'mig-' + crypto.randomBytes(12).toString('hex');
    const bodyHash = crypto.createHash('sha256').update(payload, 'utf8').digest('hex');
    const signature = crypto.createHmac('sha256', key).update('id.migrate.v1\n' + ts + '\n' + rid + '\n' + bodyHash, 'utf8').digest('hex');
    let status = 0, body = null;
    try {
      const res = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ts, request_id: rid, signature, payload }) });
      status = res.status;
      try { body = await res.json(); } catch (e) { body = null; }
    } catch (e) { status = 0; }
    const reason = body && typeof body.reason === 'string' && /^[a-z_]{1,40}$/.test(body.reason) ? body.reason : '';
    if (status === 200 && body && body.ok === true) {
      const skipped = Array.isArray(body.skipped) ? body.skipped : null;
      if (!skipped || !skipped.every((i) => Number.isInteger(i) && i >= 0 && i < people.length) || new Set(skipped).size !== skipped.length) throw new Error('bad_answer: skipped');
      const skip = new Set(skipped);
      const macs = people.filter((p, i) => !skip.has(i)).map((p) => crypto.createHmac('sha256', key).update(s(p.telegram_id), 'utf8').digest('hex'));
      return { ok: true, attempts: attempt, sent: people.length, skipped: skipped.length, counts: body.counts || {}, macs };
    }
    last = status + ' ' + (reason || 'no_reason');
    const retry = status === 0 || status === 409 || status === 429 || (status >= 500 && reason !== 'not_configured');
    if (!retry) break;
    if (attempt < 3) await wait(1000 * attempt);
  }
  throw new Error('batch_failed: ' + last);
};

// id-migrate-verify (ADR-0058). logInput OFF: the key; the output is counts and flags only.
export const code = async (inputs) => {
  const crypto = require('node:crypto');
  const s = (v) => (v === undefined || v === null ? '' : String(v));
  const key = inputs.migration_key, url = s(inputs.url), mode = s(inputs.mode), run = s(inputs.run);
  if (typeof key !== 'string' || key.length < 32 || key.includes('{{')) throw new Error('not_configured: migration_key');
  if (!/^https:\/\/[A-Za-z0-9.-]+\/api\/v1\/webhooks\/[A-Za-z0-9]+\/sync$/.test(url)) throw new Error('not_configured: url');
  if (mode !== 'test' && mode !== 'real') throw new Error('bad_mode');
  if (!/^[A-Za-z0-9_-]{1,40}$/.test(run)) throw new Error('bad_run');
  const results = Array.isArray(inputs.results) ? inputs.results : null;
  if (!results || results.some((x) => !x || x.ok !== true || !Array.isArray(x.macs))) throw new Error('bad_results');
  const n = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
  const totals = { batches: results.length, sent: 0, skipped: 0, members_inserted: 0, members_existing: 0, skipped_deleted: 0, skipped_bad: 0,
    created: { base: 0, module: 0, mailing: 0 }, existing: { base: 0, module: 0, mailing: 0 }, log_written: 0, log_repaired: 0 };
  const macs = [];
  for (const x of results) {
    totals.sent += n(x.sent); totals.skipped += n(x.skipped); macs.push(...x.macs);
    const c = x.counts || {};
    for (const k of ['members_inserted', 'members_existing', 'skipped_deleted', 'skipped_bad', 'log_written', 'log_repaired']) totals[k] += n(c[k]);
    for (const g of ['created', 'existing']) for (const p of ['base', 'module', 'mailing']) totals[g][p] += n(c[g] && c[g][p]);
  }
  if (macs.some((m) => !/^[0-9a-f]{64}$/.test(s(m)))) throw new Error('bad_results');
  const digest = crypto.createHash('sha256').update(macs.slice().sort().join('\n'), 'utf8').digest('hex');
  const payload = JSON.stringify({ kind: 'verify', mode, run, digest, sent: totals.sent, skipped: totals.skipped });
  const nowSec = () => Math.floor((Number.isFinite(inputs.now_ms) ? inputs.now_ms : Date.now()) / 1000);
  const wait = (ms) => (inputs.no_wait ? Promise.resolve() : new Promise((r) => setTimeout(r, ms)));
  let answer = null, last = 'no_attempt';
  for (let attempt = 1; attempt <= 3 && !answer; attempt++) {
    const ts = String(nowSec()), rid = 'mig-' + crypto.randomBytes(12).toString('hex');
    const h = crypto.createHash('sha256').update(payload, 'utf8').digest('hex');
    const signature = crypto.createHmac('sha256', key).update('id.migrate.v1\n' + ts + '\n' + rid + '\n' + h, 'utf8').digest('hex');
    let status = 0, body = null;
    try {
      const res = await fetch(url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ts, request_id: rid, signature, payload }) });
      status = res.status;
      try { body = await res.json(); } catch (e) { body = null; }
    } catch (e) { status = 0; }
    const reason = body && typeof body.reason === 'string' && /^[a-z_]{1,40}$/.test(body.reason) ? body.reason : '';
    if (status === 200 && body && body.ok === true) { answer = body; break; }
    last = status + ' ' + (reason || 'no_reason');
    const retry = status === 0 || status === 409 || status === 429 || (status >= 500 && reason !== 'not_configured');
    if (!retry) break;
    if (attempt < 3) await wait(1000 * attempt);
  }
  if (!answer) throw new Error('verify_failed: ' + last);
  const b = (v) => v === true || v === 'true';
  const verify = { match: b(answer.match), digest_ok: b(answer.digest_ok), count_ok: b(answer.count_ok), marked: n(answer.marked),
    wrong_range: n(answer.wrong_range), bad_marker: n(answer.bad_marker) };
  const exp = inputs.expected || {};
  const sent_ok = totals.sent === n(exp.sent);
  const accounted_ok = totals.members_inserted + totals.members_existing + totals.skipped_deleted + totals.skipped_bad === totals.sent;
  return { pass: sent_ok && accounted_ok && verify.match, sent_ok, accounted_ok, match: verify.match, totals, expected: exp, verify };
};

// id-migrate: preflight counts only, for the journal (ADR-0058). No person data.
export const code = async (inputs) => ({ ok: String(inputs.ok) === 'true', send: String(inputs.send) === 'true', reason: String(inputs.reason || ''),
  mode: String(inputs.mode || ''), run: String(inputs.run || ''), batch_count: Number(inputs.batch_count) || 0, counts: inputs.counts, expected: inputs.expected });

// id-migrate-preflight (ADR-0058). logInput/logOutput OFF: inputs and batches carry people.
export const code = async (inputs) => {
  const s = (v) => (v === undefined || v === null ? '' : String(v));
  const MODES = ['test', 'real', 'dry-test', 'dry-real'];
  const mode = s(inputs.mode).trim(), run = s(inputs.run).trim();
  const base = { ok: false, send: false, mode, run, counts: {}, expected: {}, batches: [], batch_count: 0 };
  if (!MODES.includes(mode)) return { ...base, reason: 'bad_mode' };
  if (!/^[A-Za-z0-9_-]{1,40}$/.test(run)) return { ...base, reason: 'bad_run' };
  const testMode = mode === 'test' || mode === 'dry-test', sending = mode === 'test' || mode === 'real';
  if (sending) {
    const now = Number.isFinite(inputs.now_ms) ? inputs.now_ms : Date.now();
    const until = Date.parse(s(inputs.open_until));
    if (!Number.isFinite(until) || !(now < until) || until > now + 4 * 3600 * 1000) return { ...base, reason: 'closed' };
  }
  const list = (x, name) => { const r = Array.isArray(x) ? x : (x && Array.isArray(x.records) ? x.records : null); if (!r) throw new Error('read_failed: ' + name); return r; };
  const flat = (rec) => { const o = {}, c = (rec && rec.cells) || {}; for (const k of Object.keys(c)) if (c[k] && typeof c[k] === 'object' && 'fieldName' in c[k]) o[c[k].fieldName] = c[k].value; return o; };
  const all = list(testMode ? inputs.test_all : inputs.users_all, testMode ? 'test_all' : 'users_all').map(flat);
  const trueRead = list(testMode ? inputs.test_true : inputs.users_true, testMode ? 'test_true' : 'users_true');
  const FIELDS = ['telegram_id', 'first_name', 'last_name', 'username', 'profile_first_name', 'profile_last_name',
    'position', 'company', 'city', 'lang', 'profile_completed_at', 'created_at', 'consent_pdn', 'consent_pdn_at',
    'consent_marketing', 'consent_marketing_at', 'blocked_bot'];
  const DROPS = ['consent_pdn', 'consent_marketing', 'blocked_bot'];
  const hist = {}; for (const d of DROPS) hist[d] = { true: 0, false: 0, empty: 0, other: 0 };
  const c = { rows: all.length, distinct: 0, merged_dupes: 0, disagreeing_dupes: 0, left_behind: 0, read_mismatch: 0,
    bad_value: 0, bad_id: 0, wrong_range: 0, pdn_true_no_date: 0, mkt_true_no_date: 0, too_long: 0 };
  const TEST = /^9[0-9]{15}$/, date = (v) => Number.isFinite(Date.parse(s(v)));
  const byId = new Map();
  for (const r of all) {
    const p = {};
    for (const k of FIELDS) { const v = r[k]; p[k] = v === undefined || v === null || s(v) === '' ? null : s(v); }
    for (const d of DROPS) { const v = s(p[d]); if (v === 'true' || v === 'false') hist[d][v]++; else if (v === '') hist[d].empty++; else { hist[d].other++; c.bad_value++; } }
    for (const k of FIELDS) if (p[k] !== null && p[k].length > 256) c.too_long++;
    const tid = s(p.telegram_id);
    if (!/^[1-9][0-9]{0,15}$/.test(tid)) { c.bad_id++; continue; }
    if (testMode !== TEST.test(tid)) c.wrong_range++;
    const key = JSON.stringify(FIELDS.map((k) => p[k]));
    const have = byId.get(tid);
    if (have) { if (have.key === key) c.merged_dupes++; else c.disagreeing_dupes++; continue; }
    byId.set(tid, { key, p });
  }
  if (hist.consent_pdn.true !== trueRead.length) c.read_mismatch = 1;
  c.distinct = byId.size;
  const people = [];
  let mailing = 0;
  for (const { p } of byId.values()) {
    if (p.consent_pdn !== 'true') { c.left_behind++; continue; }
    if (!date(p.consent_pdn_at)) c.pdn_true_no_date++;
    if (p.consent_marketing === 'true') { mailing++; if (!date(p.consent_marketing_at)) c.mkt_true_no_date++; }
    people.push(p);
  }
  const STOP = ['read_mismatch', 'bad_value', 'bad_id', 'wrong_range', 'disagreeing_dupes', 'pdn_true_no_date', 'mkt_true_no_date', 'too_long'];
  const stops = STOP.filter((k) => c[k] > 0);
  const counts = { ...c, hist }, expected = { sent: people.length, base: people.length, module: people.length, mailing };
  if (stops.length) return { ...base, counts, expected, reason: 'stop: ' + stops.join(',') };
  const batches = [];
  for (let i = 0; i < people.length; i += 10) batches.push(people.slice(i, i + 10));
  return { ok: true, send: sending && batches.length > 0, reason: 'ok', mode, run, counts, expected, batches, batch_count: batches.length };
};
